.sl-article-split {
    background-color: var(--smartlearn-bg);
    overflow-x: clip;
}

.sl-article-split .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-article-split .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-article-split .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-article-split .sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-article-split .sl-border { border-color: var(--smartlearn-card-border) !important; }
.sl-article-split .sl-border-primary { border-color: var(--smartlearn-primary) !important; }
.sl-article-split .sl-tracking-wide { letter-spacing: 0.1em; }

.sl-article-split .sl-media-fallback {
    background-color: var(--smartlearn-card-bg);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--smartlearn-text-muted);
}

.sl-article-split .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}

.sl-article-split .sl-split-sticky {
    height: 40vh;
    min-height: 280px;
    overflow: hidden;
}
@media (min-width: 992px) {
    .sl-article-split .sl-split-sticky {
        position: sticky;
        top: var(--smartlearn-navbar-height, 64px);
        height: calc(100vh - var(--smartlearn-navbar-height, 64px));
    }
}

.sl-article-split .sl-split-body {
    max-width: 800px;
    padding: 2rem 1.5rem;
}
@media (min-width: 768px) {
    .sl-article-split .sl-split-body { padding: 3.5rem 3rem; }
}
@media (min-width: 1200px) {
    .sl-article-split .sl-split-body { padding-block: 6rem; padding-inline: 5rem; }
}

.sl-article-split .sl-btn-cta {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid transparent;
    transition: background-color 0.2s ease;
}
.sl-article-split .sl-btn-cta:hover,
.sl-article-split .sl-btn-cta:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}

.sl-article-split.no-media .sl-split-media-col { display: none !important; }
.sl-article-split.no-media .sl-split-content-col { width: 100% !important; max-width: 100% !important; flex: 0 0 100%; }
.sl-article-split.no-media .sl-split-body { max-width: 900px; }

@media (prefers-reduced-motion: no-preference) {
    .sl-article-split .sl-editorial-img {
        transform: scale(1.05);
        will-change: transform;
    }
}
@media (prefers-reduced-motion: reduce) {
    .sl-article-split .sl-editorial-img { transform: none !important; }
    .sl-article-split .sl-btn-cta { transition: none; }
}

js:
(function() {
    function init() {
        var sections = document.querySelectorAll('.sl-article-split');
        var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        var activeItems = [];

        sections.forEach(function(section) {
            if (section.dataset.slInit === '1') return;
            section.dataset.slInit = '1';

            var img = section.querySelector('.sl-editorial-img');
            if (!img || !img.getAttribute('src') || img.getAttribute('src').trim() === '') {
                section.classList.add('no-media');
                return;
            }

            img.addEventListener('error', function() {
                section.classList.add('no-media');
            });
            if (img.complete && img.naturalWidth === 0) {
                section.classList.add('no-media');
                return;
            }

            if (!prefersReduced) {
                activeItems.push({ section: section, img: img });
            }
        });

        if (activeItems.length > 0) {
            var ticking = false;
            var update = function() {
                ticking = false;
                var vh = window.innerHeight;
                activeItems.forEach(function(item) {
                    if (item.section.classList.contains('no-media')) return;
                    var rect = item.section.getBoundingClientRect();
                    if (rect.top <= vh && rect.bottom >= 0) {
                        var pct = (vh - rect.top) / (vh + rect.height);
                        var scale = Math.max(1, 1.05 - (pct * 0.05));
                        item.img.style.transform = 'scale(' + scale.toFixed(4) + ')';
                    }
                });
            };
            window.addEventListener('scroll', function() {
                if (!ticking) {
                    ticking = true;
                    requestAnimationFrame(update);
                }
            }, { passive: true });
        }
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
